-- Tender, audit, visitor and feedback migration group.
CREATE TABLE IF NOT EXISTS tenders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source TEXT NOT NULL, source_tender_id TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_id BIGINT, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
